// A certificate of completion for a finished course, downloaded as a printable page.
// It is generated by the platform from the founder's own records; the number identifies the course and founder.

const esc = (s: string) => s.replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c] as string));

export const certificateNumber = (courseId: string, founderId: string) => `CERT-${courseId}-${founderId}`.toUpperCase();

export function certificateHtml(i: { founder: string; venture: string; course: string; modules: number; completedOn?: string; number: string }): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Certificate: ${esc(i.course)}</title>
<style>body{margin:0;font-family:Georgia,serif;background:#f0f4f7;display:flex;justify-content:center;padding:32px}
.c{background:#fff;border:10px double #3B4167;max-width:760px;width:100%;padding:56px 48px;text-align:center;color:#3B4167}
h1{font-size:34px;letter-spacing:3px;margin:0 0 6px}.s{color:#4C808A;letter-spacing:2px;font-size:13px;text-transform:uppercase;margin:0 0 36px}
.n{font-size:30px;margin:10px 0;border-bottom:2px solid #4C808A;display:inline-block;padding:0 24px 6px}.t{font-size:22px;font-weight:bold;margin:10px 0}
p{margin:8px 0;font-size:15px}.f{margin-top:40px;font-size:11px;color:#6b7280}@media print{body{background:#fff;padding:0}}</style></head>
<body><div class="c"><h1>CERTIFICATE</h1><p class="s">of completion · Emerge Livelihoods Learning Academy</p>
<p>This certifies that</p><div class="n">${esc(i.founder)}</div><p>of ${esc(i.venture)}</p>
<p>has completed all ${i.modules} modules of</p><div class="t">${esc(i.course)}</div>
<p>${i.completedOn ? `Completed on ${esc(i.completedOn)}` : "Completed"}</p>
<p class="f">Certificate no. ${esc(i.number)}</p></div></body></html>`;
}

export function downloadCertificate(i: Parameters<typeof certificateHtml>[0]) {
  const url = URL.createObjectURL(new Blob([certificateHtml(i)], { type: "text/html" }));
  Object.assign(document.createElement("a"), { href: url, download: `${i.number}.html` }).click();
  URL.revokeObjectURL(url);
}
